-- Subquery comparisons resolve their operator from the column's declared type,
-- even over an empty set; cstring has none. Type-modifier input functions.
select 'a'::cstring in (select 'a'::cstring);
select 'a' in (select 'a'::cstring);
select 1 in (select 'a'::cstring);
select 'a'::text in (select 'a'::cstring);
select 'a'::text = any (select 'a'::cstring);
select 'a'::cstring in (select 'a'::text);
select 'a' in (select x from (select 'a'::cstring x) s);
select 'a' = any (select 'a'::cstring where false);
select 'a' < all (select 'a'::cstring);
select 'a'::cstring || 'b' = any (select 'ab'::text);
select (1,'a'::cstring) in (select 1, 'a'::cstring);
select 'a'::cstring not in (select 'a'::cstring);
select 'a' like any (select 'a'::cstring);
select 1 in (select 1), 'a' in (select 'a'), 2 in (select x from (values (1),(2)) v(x));
create table tc (x text);
select x from tc where x in (select 'a'::cstring);
select x from tc where x::cstring = any (select x from tc);
select x from tc t where x in (select t.x::cstring);
drop table tc;
create table tc (x text, i int);
select x from tc where x = 1;
select x from tc where x::cstring = 'a'::cstring;
select x from tc where i in (select 'a'::text);
select x from tc where i = any (select x from tc);
select x from tc t where i in (select t.x);
select 1 where false and 'a'::cstring = 'a'::cstring;
drop table tc;
select 'abc' like any (array['a%','x']);
select 'abc' like any (select 'a%');
select 'abc' not like all (select 'a%');
select 'abc' ilike any (select 'A%' union select 'z');
select 'abc' like all (select 'a%' where false);
